public class Demo {
    public static void main(String[] args) {
        int val = 10;
        changeVal(val);
        System.out.println(val);
    }
    static void changeVal(int x) {
        x = 20;
    }
}

class Person { String name; Person(String n) { name = n; } }
public class Demo {
    public static void main(String[] args) {
        Person p = new Person("Alice");
        reassign(p);
        System.out.println(p.name);
    }
    static void reassign(Person person) {
        person = new Person("Bob");
    }
}

class Person { String name; Person(String n) { name = n; } }
public class Demo {
    public static void main(String[] args) {
        Person p = new Person("Alice");
        mutate(p);
        System.out.println(p.name);
    }
    static void mutate(Person person) {
        person.name = "Bob";
    }
}

import java.lang.ref.WeakReference;
public class Demo {
    public static void main(String[] args) {
        String ref = new String("KeepMe");
        WeakReference<String> weakRef = new WeakReference<>(ref);
        ref = null;
        System.gc();
        System.out.println(weakRef.get());
    }
}

import java.lang.ref.WeakReference;
public class Demo {
    public static void main(String[] args) {
        String ref = new String("KeepMe");
        WeakReference<String> weakRef = new WeakReference<>(ref);
        System.gc();
        System.out.println(weakRef.get() != null);
    }
}

import java.lang.ref.SoftReference;
public class Demo {
    public static void main(String[] args) {
        String ref = new String("Cached");
        SoftReference<String> softRef = new SoftReference<>(ref);
        ref = null;
        System.gc();
        System.out.println(softRef.get() != null);
    }
}

import java.lang.ref.*;
public class Demo {
    public static void main(String[] args) {
        Object obj = new Object();
        ReferenceQueue<Object> queue = new ReferenceQueue<>();
        PhantomReference<Object> phantom = new PhantomReference<>(obj, queue);
        System.out.println(phantom.get());
    }
}

public class InfiniteRecursion {
    public static void main(String[] args) {
        callSelf();
    }
    static void callSelf() {
        callSelf();
    }
}

class Resource implements AutoCloseable {
    public void close() { System.out.println("Cleaned"); }
}
public class Demo {
    public static void main(String[] args) {
        try (Resource r = new Resource()) {
            System.out.println("Active");
        }
    }
}

class Node {
    Node next;
}
public class Demo {
    public static void main(String[] args) {
        Node first = new Node();
        Node second = new Node();
        first.next = second;
        second.next = first;
        first = null;
        System.out.println(second.next != null);
    }
}

public class Demo {
    public static void main(String[] args) {
        Integer val = null;
        try {
            int prim = val;
        } catch (NullPointerException e) {
            System.out.println("NPE");
        }
    }
}
